{
  "justification": "Because this unprompted salience list is dominated by health (NHS), the economy, immigration/defence, and education/law-and-order, I weight Care highest, then Proportionality and Authority/Loyalty to reflect economic fairness, institutional order, and group cohesion. Inequality, housing, and low pay give Equality a clear but secondary role, while Purity-related concerns (drugs, environment, lifestyle) are present but relatively minor.",
  "foundations": [
    {
      "foundation": "care",
      "basis": "NHS/Hospitals/Healthcare; Ageing population/Social care; Housing; Education/Schools (child wellbeing); Pollution/Environment; Drug abuse; Animal welfare",
      "weight": 0.34
    },
    {
      "foundation": "proportionality",
      "basis": "Economy/Economic situation; Unemployment/Factory closure/Lack of industry; Inflation/Prices; Taxation; Low pay/Minimum wage/Fair wages; Privatisation; Pensions/Social security (deservingness debates)",
      "weight": 0.22
    },
    {
      "foundation": "authority",
      "basis": "Crime/Law and order/Violence/Vandalism; Defence/Foreign affairs/International terrorism; Local government/Council tax/Poll tax; Education/Schools (discipline/socialization); Public services in general; Lack of faith in govt/politics",
      "weight": 0.18
    },
    {
      "foundation": "loyalty",
      "basis": "Immigration; Defence/Foreign affairs/International terrorism; Common Market/EU/Europe/Single European Currency; Scottish/Welsh Assembly/Devolution; Race relations (group cohesion)",
      "weight": 0.12
    },
    {
      "foundation": "equality",
      "basis": "Poverty/Inequality; Housing; Pensions/Social security; Low pay/Minimum wage/Fair wages; Education/Schools (equal opportunity); Race relations",
      "weight": 0.10
    },
    {
      "foundation": "sanctity",
      "basis": "Drug abuse; Pollution/Environment; Morality/Individual behaviour/Lifestyle; Animal welfare; Nuclear weapons/Disarmament (sanctity of life)",
      "weight": 0.04
    }
  ]
}
